import { test, expect } from '@playwright/test';

test.describe('Search Filter - No Results Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should display "No results found" when no items match search query', async ({ page }) => {
    // Set up API interception for search endpoint
    await page.route('**/api/search', (route) => {
      route.abort('no results');
    });

    // Set up intercept for no results response
    await page.route('**/api/search', (route) => {
      route.continue();
    });

    // Set up intercept for successful search response
    await page.route('**/api/search', (route) => {
      route.continue();
    });

    // Set up intercept for error response
    await page.route('**/api/search', (route) => {
      route.abort('error');
    });

    // Perform search with no results
    const searchInput = page.getByLabel('Search');
    await searchInput.fill('nonexistent item');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for results to load
    await page.waitForResponse(response => response.url().includes('/search') && response.status() === 200);

    // Verify no results message is displayed
    const noResultsMessage = page.getByText('No results found');
    await expect(noResultsMessage).toBeVisible();

    // Verify search input is still visible
    await expect(searchInput).toBeVisible();

    // Verify search button is still visible
    await expect(searchButton).toBeVisible();

    // Verify search results container is empty
    const resultsContainer = page.locator('[data-testid="search-results-container"]');
    await expect(resultsContainer).toHaveCount(0);
  });

  test('should handle error state when search API fails', async ({ page }) => {
    // Set up API interception for search endpoint
    await page.route('**/api/search', (route) => {
      route.abort('error');
    });

    // Set up intercept for successful search response
    await page.route('**/api/search', (route) => {
      route.continue();
    });

    // Set up intercept for no results response
    await page.route('**/api/search', (route) => {
      route.continue();
    });

    // Perform search with error condition
    const searchInput = page.getByLabel('Search');
    await searchInput.fill('error test');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for error state to be displayed
    await page.waitForResponse(response => response.url().includes('/search') && response.status() === 500);

    // Verify error message is displayed
    const errorMessage = page.getByText('Search failed');
    await expect(errorMessage).toBeVisible();

    // Verify search input is still visible
    await expect(searchInput).toBeVisible();

    // Verify search button is still visible
    await expect(searchButton).toBeVisible();

    // Verify error state is active
    const errorState = page.getByRole('status');
    await expect(errorState).toBeVisible();

    // Verify no results message is not displayed
    const noResultsMessage = page.getByText('No results found');
    await expect(noResultsMessage).not.toBeVisible();
  });
});
